package jp.schoolboard;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
public class BoardWidget extends AppWidgetProvider {
 static PendingIntent action(Context c,String action,String value,int id){Intent i=new Intent(c,BoardWidget.class).setAction(action).setData(android.net.Uri.parse("schoolboard://"+id+"/"+action+"/"+value)).putExtra("value",value).putExtra("widget",id);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent open(Context c,boolean add){return PendingIntent.getActivity(c,add?1:0,new Intent(c,MainActivity.class).putExtra("add",add),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public void onReceive(Context c,Intent i){super.onReceive(c,i);if("tab".equals(i.getAction())){Store.p(c).edit().putString("tab"+i.getIntExtra("widget",0),i.getStringExtra("value")).apply();refresh(c);}if("done".equals(i.getAction()))Store.toggle(c,i.getStringExtra("value"));}
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)render(c,m,id);}
 static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,BoardWidget.class)))render(c,m,id);}
 static void render(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);String tab=Store.p(c).getString("tab"+id,"tasks");v.setTextViewText(R.id.title,"SCHOOL BOARD  ·  "+LocalDate.now().toString());v.setOnClickPendingIntent(R.id.title,open(c,false));v.setOnClickPendingIntent(R.id.add,open(c,true));int[] buttons={R.id.tasks,R.id.lessons,R.id.events};String[] names={"tasks","lessons","events"};for(int j=0;j<3;j++){v.setOnClickPendingIntent(buttons[j],action(c,"tab",names[j],id));v.setTextColor(buttons[j],names[j].equals(tab)?0xff7ee4d0:0xff91a0b7);}v.removeAllViews(R.id.rows);List<JSONObject> tasks=Store.pending(c);List<String> lines=tab.equals("tasks")?new ArrayList<>():Store.lines(c,tab);if(tab.equals("tasks"))for(JSONObject o:tasks)lines.add("○  "+o.optString("title")+"\n"+o.optString("due")+"  ·  "+o.optString("subject"));if(lines.isEmpty())lines.add(tab.equals("tasks")?"提出物はありません\n登録忘れがないか確認しよう":"予定はありません · アプリからデータを登録");for(int j=0;j<Math.min(3,lines.size());j++){RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.row);row.setTextViewText(R.id.row,lines.get(j));row.setOnClickPendingIntent(R.id.row,tab.equals("tasks")&&!tasks.isEmpty()?action(c,"done",tasks.get(j).optString("id"),id):open(c,false));v.addView(R.id.rows,row);}m.updateAppWidget(id,v);}
}